init:
root => {
  var links = [].slice.call(root.querySelectorAll('[data-to]'));
  if (!links.length) return;
  links.forEach(function (a) {
    a.addEventListener('click', function (e) {
      e.preventDefault();
      links.forEach(function (x) { x.classList.toggle('d-it-on', x === a); });
    });
  });
}
